class RunReopen(BaseModel):
    """
    Body of `POST /v1/runs/{id}/reopen`.

    `session_id` is the relaunching process's writer fingerprint. It is what the
    reopen records and what makes the new attempt distinguishable from the dead
    one it continues -- two executions on one run's curve are otherwise
    indistinguishable after the fact. It is also the reopen's idempotency key:
    a retry carrying the session that already reopened this run gets the same
    receipt back instead of a conflict, so a lost response is recoverable.

    `rewind_to_step` (0185) asks for a checkpoint rewind: every step-indexed
    record at or above it is discarded inside the reopen transaction, so the
    relaunch can REWRITE that range instead of colliding with first-write-wins
    identity slots. Destructive by explicit request only -- omitted means
    nothing is ever deleted. Its presence also unlocks reopening a `completed`
    incumbent: a deliberate stop-then-rewind is the flag's primary use, and
    spelling the step out IS the deliberate consent the completed 409 exists
    to demand from a plain resume.
    """

    expected_write_epoch: ExpectedWriteEpoch | None = Field(
        None, title='Expected Write Epoch'
    )
    keep_epoch: bool | None = Field(False, title='Keep Epoch')
    rewind_to_step: RewindToStep | None = Field(None, title='Rewind To Step')
    session_id: UUID = Field(..., title='Session Id')
    takeover_stale_after_seconds: TakeoverStaleAfterSeconds | None = Field(
        None, title='Takeover Stale After Seconds'
    )
    writer: WriterLeaseIn | None = None


