class RunCodeCompareOut(BaseModel):
    """
    `GET /v1/runs/{ref}/code/compare?to=...`: what changed in code between
    two runs.

    DIRECTION: `base` is the OLDER run by its own clock (started_at, with
    created_at as the fallback for a run that never started) and `head` the
    newer, whichever order the URL named them in; `commits` reads OLDEST FIRST
    (base -> head), inclusive of both endpoint shas. STORED ROWS ONLY (v1),
    like the experiment window: the commits listed are the ones this tenant's
    runs resolved to in that span, never the full git range.
    """

    base: RunCodeCompareSide
    commits: list[LinkedCommitRow] | None = Field(None, title='Commits')
    commits_truncated: bool | None = Field(False, title='Commits Truncated')
    head: RunCodeCompareSide
    identical: bool | None = Field(False, title='Identical')
    repo: str | None = Field(None, title='Repo')
    state: RunCompareState
    swapped: bool | None = Field(False, title='Swapped')


class SearchResponse(BaseModel):
    dropped_chunk_count: int | None = Field(0, title='Dropped Chunk Count')
    dropped_result_count: int | None = Field(0, title='Dropped Result Count')
